// ===== TOWNVOICE: generated by tools/voice/record-town.js, do not edit. The townsfolk's story lines, in order, the Journal page each needs, and the length of its recording (audio/town/<id>.mp3). =====
try{window.TOWNVOICE={"mira_1":{"npc":"mira","need":"always","text":"Did Lavi tell you? You can hear the Rootways. Wonderful. Can you hear any customers in there?","dur":5.45},"mira_2":{"npc":"mira","need":"w0_word","text":"You woke a whole world? Then it will need shopping. I'm opening a stall there. Possibly. Eventually.","dur":6.14},"mira_3":{"npc":"mira","need":"dg_first","text":"A buried Rootway! Did you find anything shiny down there? Asking for a friend. The friend is me.","dur":6.1},"mira_4":{"npc":"mira","need":"end","text":"Every world open again, and my stall in all of them. Thank you, {name}. Truly. Now buy something.","dur":5.62},"oak_1":{"npc":"oak","need":"silence","text":"Before the Silence, the roots carried songs between the worlds. Some nights I still hear the echo.","dur":6.98},"oak_2":{"npc":"oak","need":"w0_guard","text":"Thornmaw guarded those roots for a hundred years. Thank you for letting it rest gently.","dur":6.43},"oak_3":{"npc":"oak","need":"end","text":"The roots are singing again. I had forgotten how loud joy can be.","dur":5.16},"bram_1":{"npc":"bram","need":"w1_seen","text":"You've been to the Inferno. Cold forges, aren't they. I learned to hammer there. It was never cold, back then.","dur":8.18},"bram_2":{"npc":"bram","need":"w1_word","text":"The forges are singing again? Hah! ...Something in my eye. Sparks. It's the sparks.","dur":6.24},"bram_3":{"npc":"bram","need":"w1_guard","text":"Vulkhar finally put the hammer down. Good. Pride burns longer than coal, and it gives no heat.","dur":7.97},"hana_1":{"npc":"hana","need":"w0_word","text":"My seeds sprouted this morning! All of them at once! Did you do something? You did something.","dur":5.19},"hana_2":{"npc":"hana","need":"w0_guard","text":"The garden is blooming like it remembers how. Come and smell the roses, {name}. That's an order.","dur":5.2},"seren_1":{"npc":"seren","need":"silence","text":"The Great Silence isn't a sound. It's an absence. Like a word on the tip of your tongue, for a hundred years.","dur":6.34},"seren_2":{"npc":"seren","need":"w2_seen","text":"You saw the stars going out. I count them every night. Last night, one fewer.","dur":4.47},"seren_3":{"npc":"seren","need":"w2_guard","text":"New stars! Three of them, over the Galaxy. I named one after you. It's the slightly crooked one.","dur":5.53},"seren_4":{"npc":"seren","need":"end","text":"I spent my life trying to understand the Silence. In the end, understanding mattered less than remembering.","dur":6},"kael_1":{"npc":"kael","need":"w3_seen","text":"You went to the Abyssal Sea. Did you see a lighthouse? ...No. Never mind. Forget I asked.","dur":5.04},"kael_2":{"npc":"kael","need":"w3_guard","text":"Someone lit the lighthouse on the Abyssal Sea. Only one person ever knew how. ...I need to sit down.","dur":6.23},"kael_3":{"npc":"kael","need":"end","text":"She came home. She's at the gate every evening, arguing with me about the patrol route. It's wonderful.","dur":5.83},"pip_1":{"npc":"pip","need":"always","text":"Lavi says you can hear the roots! What are they saying? Is it about me?","dur":3.35},"pip_2":{"npc":"pip","need":"w0_guard","text":"You beat Thornmaw?! I'm telling everyone. I already told everyone. I'm telling them again.","dur":4.72},"pip_3":{"npc":"pip","need":"dg_first","text":"Take me to a dungeon next time! I'll be so quiet. Watch. ...This is me being quiet.","dur":4.64},"lulu_1":{"npc":"lulu","need":"w4_seen","text":"The Crystal Realm... I danced at that festival once. I was the best dancer there. Tobi says I fell over. Tobi is wrong.","dur":6.37},"lulu_2":{"npc":"lulu","need":"w4_guard","text":"The dancers are moving again? Then I'm going back. And this time, I'm not falling over.","dur":4.21},"tobi_1":{"npc":"tobi","need":"always","text":"I baked a loaf to celebrate you waking up! It's a little burnt. I baked it a hundred years ago.","dur":4.86},"tobi_2":{"npc":"tobi","need":"w1_word","text":"The Inferno's forges are hot again? Perfect oven weather. Could you bring me some of that heat?","dur":4.47},"tobi_3":{"npc":"tobi","need":"end","text":"A festival! I'm baking for everyone! I've only burnt three loaves so far. That's a record.","dur":4.72},"ren_1":{"npc":"ren","need":"silence","text":"I walked the Rootways, before. Every world had a road home. I'm still looking for mine.","dur":5.6},"ren_2":{"npc":"ren","need":"w2_word","text":"There's a scholar in the Galaxy who works with Seren. Stubborn, short, laughs like my sister. ...I have to go.","dur":7.15},"ren_3":{"npc":"ren","need":"end","text":"I found her. She was there all along, counting stars, waiting for someone to remember her name.","dur":6.16},"lumi_1":{"npc":"lumi","need":"w2_seen","text":"...you saw my home. The stars. Were there any left?","dur":2.92},"lumi_2":{"npc":"lumi","need":"w2_guard","text":"My family's lights are back in the sky. I can see them from the stone lantern. ...Thank you.","dur":5.25},"vesper_1":{"npc":"vesper","need":"always","text":"Since the Silence, I see nothing in my crystal ball. It's very relaxing. Terrible for business.","dur":5.94},"vesper_2":{"npc":"vesper","need":"w0_word","text":"Ooh. A flicker in the crystal. I see... a word. And you. And quite a lot of trouble. Wonderful!","dur":5.45},"vesper_3":{"npc":"vesper","need":"end","text":"My last vision: lanterns, music and a festival in the Plaza. For once, I'm glad to be right.","dur":6.28},"side_pip_ask":{"npc":"pip","need":"side","text":"I found a dragon egg! Well, I lost it. Can you find me a round stone? Break some stone blocks and bring me the roundest one.","dur":6.28},"side_pip_done":{"npc":"pip","need":"side","text":"A dragon egg! ...It's a rock. It's the best rock. I'm going to name it Kevin.","dur":3.81},"side_hana_ask":{"npc":"hana","need":"side","text":"I have one last seed from before the Silence. Plant five seeds for me first, to warm up the soil?","dur":6.44},"side_hana_done":{"npc":"hana","need":"side","text":"The soil is warm. I planted the old seed beside yours. I think it's going to remember how to grow.","dur":6.52},"side_bram_ask":{"npc":"bram","need":"side","text":"I'm forging one perfect blade, but I need to watch a fighter work. Defeat twenty monsters. Anything sharp will do.","dur":9.26},"side_bram_done":{"npc":"bram","need":"side","text":"Good. Every swing told me something. The blade is nearly ready. So are you.","dur":5.86},"side_tobi_ask":{"npc":"tobi","need":"side","text":"My grandmother's bread needs Inferno heat. Could you bring me five Magma Shards from the Inferno's monsters?","dur":5.95},"side_tobi_done":{"npc":"tobi","need":"side","text":"It's rising! It's golden! It's only a little burnt. Grandmother would be proud.","dur":4},"side_kael_ask":{"npc":"kael","need":"side","text":"Take this letter to the Abyssal Sea. Leave it by the water. Don't read it. ...You can read it.","dur":5.27},"side_kael_done":{"npc":"kael","need":"side","text":"You left it by the water? Then she'll know I never stopped waiting. Thank you.","dur":4.27},"side_lumi_ask":{"npc":"lumi","need":"side","text":"...my lantern. I left it in the Galaxy, a hundred years ago. Could you look for it, at night?","dur":4.95},"side_lumi_done":{"npc":"lumi","need":"side","text":"You found its light. It was still glowing. It waited for me.","dur":3.38},"side_lulu_ask":{"npc":"lulu","need":"side","text":"The festival bell went missing in the Crystal Realm. Without it, nobody knows when to dance. Could you find it?","dur":5.54},"side_lulu_done":{"npc":"lulu","need":"side","text":"The bell! Listen to it... Pip, stop ringing it. Pip. Pip!","dur":2.97},"side_mira_ask":{"npc":"mira","need":"side","text":"Someone left a music box with me before the Silence, and it went missing down a dungeon. Any dungeon. It plays a lullaby.","dur":7.49},"side_mira_done":{"npc":"mira","need":"side","text":"My music box! It still plays. It's the song my mother hummed. Don't tell anyone I cried. Here. A discount. A small one.","dur":7.72}}}catch(e){console.error('TOWNVOICE',e)}
